```java
import com.opencsv.CSVReader;
import java.io.FileReader;
import java.util.ArrayList;
import java.util.List;
public class MagneticFieldData {
    private String location;
    private double latitude;
    private double longitude;
    private double magneticFieldIntensity;
    public MagneticFieldData(String location, double latitude, double longitude, double magneticFieldIntensity) {
        this.location = location;
        this.latitude = latitude;
        this.longitude = longitude;
        this.magneticFieldIntensity = magneticFieldIntensity;
    }
    // Getters and setters
    public static void main(String[] args) throws Exception {
        List<MagneticFieldData> dataList = new ArrayList<>();
        try (CSVReader reader = new CSVReader(new FileReader("magnetic_field_data.csv"))) {
            String[] line;
            while ((line = reader.readNext()) != null) {
                dataList.add(new MagneticFieldData(line[0], Double.parseDouble(line[1]), Double.parseDouble(line[2]), Double.parseDouble(line[3])));
            }
        }
        // Analyze the data here
        double totalIntensity = 0.0;
        for (MagneticFieldData data : dataList) {
            totalIntensity += data.getMagneticFieldIntensity();
            System.out.println("Location: " + data.getLocation() + ", Magnetic Field Intensity: " + data.getMagneticFieldIntensity());
        }
        double averageIntensity = totalIntensity / dataList.size();
        System.out.println("Average Magnetic Field Intensity: " + averageIntensity);
    }
}
```
