 Certainly! Here's a JavaScript function that uses regular expressions to identify and swap the positions of adjectives and their modifiers in a given sentence:

```javascript
function switchAdjectiveOrder(sentence) {
  // Define an array containing common English adjective endings
  const adjectiveEndings = /[ljwz]$/; // l, j, w, or z as the last letter

  // Split the sentence into words
  const words = sentence.split(' ');

  let result = [];

  for (let i = 0; i < words.length; i++) {
    const word = words[i];

    // Check if the current word is an adjective
    if (isAdjective(word)) {
      // If there's another word before it, save its position
      const previousWordIndex = i - 1 >= 0 ? i - 1 : -1;

      // Save the adjective and its modifier(s) in an object
      const adjectiveWithModifier = {
        adjective: word,
        modifier: words[i + 1],
      };

      // Remove the adjective and its modifier from the original array
      if (previousWordIndex !== -1 && isAdjective(words[previousWordIndex])) {
        const modifier = words[i + 1];
        words.splice(i, 3, words[i - 1], modifier, adjectiveWithModifier.adjective);
      } else {
        result.push(adjectiveWithModifier.adjective);
        i += 1;
      }
    } else {
      result.push(word);
    }
  }

  // Join the words back into a single string, with spaces between them
  return result.join(' ') + ' ' + result.pop(); // Add the last word without any space
}

// Helper function to check if a given word is an adjective based on its ending
function isAdjective(word) {
  return adjectiveEndings.test(word);
}

