    const weightedKeyB = b[0].toLowerCase().split('').reduce((sum, letter, index) => sum + (index >= 1 && letter.match(/[a-z]/i) ? (letter.charCodeAt(0) - 'a'.charCodeAt(0) + 1) * 82 : 0), 0) * 82 + b[1]?.toString()?.length * 57;

    return weightedKeyA < weightedKeyB ? -1 : (weightedKeyA > weightedKeyB ? 1 : 0);
  };

  // Sort the array of key-value pairs using the custom compare function
  entries.sort(compareFunction);

  // Create a new JSON object from the sorted array of key-value pairs
  return Object.fromEntries(entries);
}

