```javascript
function searchPlacesAndLogCoordinates() {
  // Replace "SheetName" with the name of your Google Spreadsheet sheet.
  const sheetName = "SheetName";
  const apiKey = "YOUR_API_KEY"; // Get your Google Maps API key
  const service = Maps.newGeocoder();
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const sheet = ss.getActiveSheet();
  const dataRange = sheet.getDataRange();
  const values = dataRange.getValues();

  for (let i = 0; i < values.length; i++) {
    const address = values[i][0]; // Assuming the address is in the first column
    try {
      const location = service.geocode(address);
      if (location.status === "OK") {
        const lat = location.results[0].geometry.location.lat;
        const lng = location.results[0].geometry.location.lng;
        sheet.getRange(i + 1, 2).setValue(lat); // Set latitude in the second column
        sheet.getRange(i + 1, 3).setValue(lng); // Set longitude in the third column
      } else {
        Logger.log(`Error geocoding ${address}: ${location.error.message}`);
      }
    } catch (e) {
      Logger.log(`Error: ${e.message}`);
    }
  }
}
