```php
<?php
$servername = "localhost";
$username = "username";
$password = "password";
$dbname = "coffee_shop";

// Create connection
$conn = new mysqli($servername, $username, $password, $dbname);

// Check connection
if ($conn->connect_error) {
    die("Connection failed: " . $conn->connect_error);
}

// Set up query to find customers who have purchased a specific product at least three times in a week
$query = "SELECT customers.name, COUNT(*) as purchase_count 
          FROM transactions 
          JOIN products ON transactions.product_id = products.id 
          JOIN customers ON transactions.customer_id = customers.id 
          WHERE products.name = 'desired_product' AND WEEKOFYEAR(transactions.date) = WEEKOFYEAR(NOW()) 
          GROUP BY customers.id 
          HAVING purchase_count >= 3";

$result = $conn->query($query);

// Output data of each row
if ($result->num_rows > 0) {
    echo "<table><tr><th>Customer Name</th><th>Number of Purchases</th></tr>";
    while($row = $result->fetch_assoc()) {
        echo "<tr><td>" . $row["name"]. "</td><td>" . $row["purchase_count"]. "</td></tr>";
    }
    echo "</table>";
} else {
    echo "0 results";
}

// Close connection
$conn->close();
?>
```

