To use GridFS with Node.js and Express:

1. Install the `gridfs-stream` package:
   ```
   npm install gridfs-stream --save
   ```

2. Set up your MongoDB connection:
   ```javascript
   const fs = require('fs');
   const GridFsStorage = require('multer-gridfs-storage').GridFsStorage;
   const Grid = require('gridfs-stream');
   const mongoose = require('mongoose');

   const conn = mongoose.createConnection('mongodb://localhost:27017/mydatabase', { useNewUrlParser: true, useUnifiedTopology: true });
   const gfs = Grid(conn);

   const storage = new GridFsStorage({ url: 'mongodb://localhost:27017/mydatabase', file: (req, file) => `${file.originalname}-${Date.now()}` });

   const upload = multer({ storage });
   ```

3. Use the middleware to handle image uploads:
   ```javascript
   app.post('/upload', upload.single('image'), function (req, res, next) {
     // 'image' is the name of the input field in the form used to choose the file
     // req.file is the 'image' file
     res.send('File uploaded successfully.');
     fs.unlinkSync(req.file.path); // Remove uploaded temp file
   });
   ```

4. Retrieve an image:
