function removeWidows(text, lineHeight) {
  const lines = text.split('\n');
  const paragraphs = [];
  let currentParagraph = [];

  lines.forEach((line) => {
    if (line === '' || line.match(/^[.\?!]$/) || currentParagraph.length + line.split(' ').length > lineHeight) {
      // New paragraph or end of line, add previous paragraph to list
      if (currentParagraph.length > 0) {
        paragraphs.push(currentParagraph);
        currentParagraph = [];
      }
    } else {
      currentParagraph.push(line);
    }
  });

  // Add last paragraph to list
  if (currentParagraph.length > 0) {
    paragraphs.push(currentParagraph);
  }

  return paragraphs;
}

