 Here's an example implementation of the `RedisClient` class according to your specifications:

```javascript
const redis = require('redis');

class RedisClient {
  constructor() {
    this.client = new redis();
    this.client.on('error', (err) => {
      console.error(`Error connecting to Redis: ${err}`);
    });
  }

  isAlive() {
    return this.client.connected;
  }

  async get(key) {
    return new Promise((resolve, reject) => {
      this.client.get(key, (err, value) => {
        if (err) {
          return reject(err);
        }
        resolve(value);
      });
    });
  }

  async set(key, value, duration) {
    return new Promise((resolve, reject) => {
      this.client.set(key, value, 'EX', duration, (err, reply) => {
        if (err) {
          return reject(err);
        }
        resolve(reply);
      });
    });
  }

  async del(key) {
    return new Promise((resolve, reject) => {
      this.client.del(key, (err, reply) => {
        if (err) {
          return reject(err);
        }
        resolve(reply);
      });
    });
  }
}

const redisClient = new RedisClient();
module.exports = { RedisClient, redisClient };
```

This code defines the `RedisClient` class with the required methods, and exports both the class and an instance of it named `redisClient`. The constructor sets up the connection to Redis and listens for errors. The methods `get`, `set`, and `del` are implemented using Promises for asynchronous execution.

